_batman_icon_cache = None


def load_batman_icon():
    """Return a QIcon of the Batman logo, decoded once and cached."""
    global _batman_icon_cache

    if _batman_icon_cache is None:
        raw = base64.b64decode(_BATMAN_LOGO_B64)
        pixmap = QPixmap()
        pixmap.loadFromData(QByteArray(raw), "PNG")
        _batman_icon_cache = QIcon(pixmap)

    return _batman_icon_cache


