_wallpaper_applied = False


def ensure_batman_wallpaper():
    """Set the real Windows desktop wallpaper to the Batman image.
    Safe to call every launch -- cheap and idempotent."""
    global _wallpaper_applied

    if _wallpaper_applied:
        return

    try:
        assets_dir = Path(__file__).resolve().parent / "assets"
        assets_dir.mkdir(exist_ok=True)
        wallpaper_path = assets_dir / "batman_wallpaper.jpg"

        if not wallpaper_path.exists():
            raw = base64.b64decode(_BATMAN_WALLPAPER_B64)
            wallpaper_path.write_bytes(raw)

        SPI_SETDESKWALLPAPER = 20
        SPIF_UPDATEINIFILE = 0x01
        SPIF_SENDCHANGE = 0x02

        ctypes.windll.user32.SystemParametersInfoW(
            SPI_SETDESKWALLPAPER,
            0,
            str(wallpaper_path),
            SPIF_UPDATEINIFILE | SPIF_SENDCHANGE,
        )

        _wallpaper_applied = True
        print("[26] Desktop wallpaper set to Batman background.")

    except Exception as error:
        print("[26] Could not set desktop wallpaper:", repr(error))


def minimize_own_console():
    """If 26 was started from a visible Command Prompt (e.g. running
    `py limra_hud.py` by hand to watch the logs -- exactly how it's
    been getting tested), that console is a real window sitting in
    the background the whole time. It can briefly flash into view
    during the hide/reveal transition when launching an app, since
    it's just another window in the Z-order.

    Minimizing it up front removes it from that equation entirely.
    It's still right there in the taskbar/Alt+Tab whenever you want
    to check the logs — this only stops it from getting exposed by
    accident.

    When 26 is started normally via the Startup shortcut, it runs
    under pythonw.exe, which has no console window at all -- so this
    is a harmless no-op in that case (GetConsoleWindow returns NULL).
    """
    try:
        kernel32 = ctypes.windll.kernel32
        user32 = ctypes.windll.user32

        console_hwnd = kernel32.GetConsoleWindow()
        if console_hwnd:
            SW_MINIMIZE = 6
            user32.ShowWindow(console_hwnd, SW_MINIMIZE)

    except Exception as error:
        print("[26] Could not minimize console window:", repr(error))



