# ============================================================
# FONT SYSTEM
# ============================================================

# ============================================================
# DESKTOP DOCKING
# ============================================================
#
# When True, 26 attaches itself to the same "WorkerW" layer that
# Windows uses to host rich/live wallpapers (the same trick tools
# like Wallpaper Engine and Rainmeter use). Docked this way, 26
# sits BEHIND every normal application window automatically, via
# Windows' own window stacking -- exactly like your desktop
# wallpaper does. That means opening any app simply covers 26 the
# way it would cover your wallpaper, with nothing to hide and
# nothing to restore; closing/minimizing that app reveals 26 again
# on its own.
#
# This relies on an undocumented (but very long-standing, and
# widely relied upon by other wallpaper tools) piece of Windows
# behavior. If it doesn't work on a given machine/Windows build,
# 26 automatically falls back to the previous always-on-top mode
# with the hide/restore watchdog, so it keeps working either way.
# Set this to False to skip the attempt entirely and always use
# the always-on-top fallback.
ENABLE_DESKTOP_DOCK = True


def get_batman_font():

    available = set(
        QFontDatabase.families()
    )

    preferred_fonts = [
        "Agency FB",
        "BankGothic Md BT",
        "Bank Gothic",
        "Bahnschrift SemiCondensed",
        "Bahnschrift",
        "Arial Narrow",
        "Consolas",
    ]

    for font in preferred_fonts:

        if font in available:
            return font

    return "Arial"



# ============================================================
# 26 CORE
# ============================================================

class CoreWidget(QWidget):

    def __init__(self):

        super().__init__()

        self.batman_font = get_batman_font()

        self.angle = 0
        self.pulse = 0
        self.direction = 1

        # Smaller than previous version so
        # the lower system information stays visible.
        self.setMinimumSize(240, 240)
        self.setMaximumSize(300, 300)

        self.timer = QTimer(self)

        self.timer.timeout.connect(
            self.animate
        )

        self.timer.start(35)

    def animate(self):

        self.angle = (
            self.angle + 1
        ) % 360

        self.pulse += (
            self.direction * 0.3
        )

        if self.pulse >= 6:
            self.direction = -1

        if self.pulse <= 0:
            self.direction = 1

        self.update()

    def paintEvent(self, event):

        painter = QPainter(self)

        painter.setRenderHint(
            QPainter.RenderHint.Antialiasing
        )

        center = self.rect().center()

        cx = center.x()
        cy = center.y()

        # ====================================================
        # OUTER RINGS
        # ====================================================

        rings = [
            (235, 20),
            (205, 32),
            (175, 45),
        ]

        for size, alpha in rings:

            pen = QPen(
                QColor(
                    150,
                    150,
                    150,
                    alpha
                )
            )

            pen.setWidth(1)

            painter.setPen(pen)

            painter.drawEllipse(
                QRectF(
                    cx - size / 2,
                    cy - size / 2,
                    size,
                    size
                )
            )

        # ====================================================
        # ANGULAR ROTATING ARC
        # ====================================================

        pen = QPen(
            QColor(
                190,
                190,
                190,
                145
            )
        )

        pen.setWidth(2)

        painter.setPen(pen)

        painter.drawArc(
            QRectF(
                cx - 117,
                cy - 117,
                234,
                234
            ),
            self.angle * 16,
            55 * 16
        )

        # ====================================================
        # SECOND ARC
        # ====================================================

        pen2 = QPen(
            QColor(
                90,
                90,
                90,
                100
            )
        )

        pen2.setWidth(1)

        painter.setPen(pen2)

        painter.drawArc(
            QRectF(
                cx - 100,
                cy - 100,
                200,
                200
            ),
            -self.angle * 10,
            35 * 16
        )

        # ====================================================
        # CORE
        # ====================================================

        core_size = 92 + self.pulse

        painter.setPen(
            QPen(
                QColor(
                    120,
                    120,
                    120,
                    170
                ),
                1
            )
        )

        painter.setBrush(
            QColor(
                18,
                18,
                18
            )
        )

        painter.drawEllipse(
            QPointF(
                cx,
                cy
            ),
            core_size / 2,
            core_size / 2
        )

        # ====================================================
        # 26
        # ====================================================

        painter.setPen(
            QColor(
                225,
                225,
                225
            )
        )

        painter.setFont(
            QFont(
                self.batman_font,
                36,
                QFont.Weight.Bold
            )
        )

        painter.drawText(
            QRectF(
                cx - 60,
                cy - 35,
                120,
                70
            ),
            Qt.AlignmentFlag.AlignCenter,
            "26"
        )


