# ============================================================
# QUICK SETTINGS FLYOUT
# ============================================================
#
# A Batman-styled equivalent of the Windows quick-settings flyout
# (the little panel that pops up from Wi-Fi/Bluetooth/volume in the
# taskbar). Wi-Fi and Bluetooth show LIVE status and hand off to the
# real Windows settings page to change anything — actually flipping
# those radios from an unprivileged background app is unreliable
# across Windows versions and often needs admin rights, so rather
# than fake a toggle that silently does nothing, clicking OPEN takes
# you straight to the real control. Friday's mic and the power
# actions (lock/sleep) ARE fully real, since those are entirely
# under 26's own control.
# ============================================================

# ============================================================
# BACKGROUND TASK WORKER
# ============================================================
#
# netsh/PowerShell calls (Wi-Fi scan, Bluetooth lookup, connecting)
# take anywhere from ~200ms to a couple of seconds. Running them
# directly on the GUI thread — which is exactly what the first
# version of this panel did — freezes the whole app for that long,
# including the rotating ring animation on 26's main dial. This
# worker runs the blocking call on a background thread and hands
# the result back to the GUI thread via a signal, so the UI (and the
# ring) never stalls.

class _BackgroundTask(QThread):

    done = pyqtSignal(object)

    def __init__(self, fn, parent=None):
        super().__init__(parent)
        self._fn = fn

    def run(self):
        try:
            result = self._fn()
        except Exception as error:
            print("[26] Background task failed:", repr(error))
            result = None

        self.done.emit(result)


class QuickSettingsPanel(QFrame):

    def __init__(self, hud):

        super().__init__(hud)

        self.hud = hud

        self.setObjectName("quickSettings")

        self.setWindowFlags(
            Qt.WindowType.FramelessWindowHint |
            Qt.WindowType.Tool
        )

        self.setFixedWidth(320)

        self.hide()

        layout = QVBoxLayout()

        layout.setContentsMargins(18, 16, 18, 16)
        layout.setSpacing(10)

        title = QLabel("26  //  QUICK SETTINGS")
        title.setObjectName("edition")
        layout.addWidget(title)

        # ---- WI-FI -------------------------------------------------
        self.wifi_row = self._make_row(
            "WI-FI", "--", "NETWORKS", self.toggle_wifi_list
        )
        layout.addLayout(self.wifi_row["layout"])

        self.wifi_list = QWidget()
        self.wifi_list_layout = QVBoxLayout(self.wifi_list)
        self.wifi_list_layout.setContentsMargins(4, 2, 4, 6)
        self.wifi_list_layout.setSpacing(4)
        self.wifi_list.hide()
        layout.addWidget(self.wifi_list)

        # ---- BLUETOOTH ----------------------------------------------
        self.bluetooth_row = self._make_row(
            "BLUETOOTH", "--", "DEVICES", self.toggle_bluetooth_list
        )
        layout.addLayout(self.bluetooth_row["layout"])

        self.bluetooth_list = QWidget()
        self.bluetooth_list_layout = QVBoxLayout(self.bluetooth_list)
        self.bluetooth_list_layout.setContentsMargins(4, 2, 4, 6)
        self.bluetooth_list_layout.setSpacing(4)
        self.bluetooth_list.hide()
        layout.addWidget(self.bluetooth_list)

        # ---- SOUND ----------------------------------------------------
        self.sound_row = self._make_row(
            "SOUND", "", "MIXER", self.open_sound_settings
        )
        layout.addLayout(self.sound_row["layout"])

        # ---- FRIDAY VOICE ----------------------------------------------
        self.voice_row = self._make_row(
            "FRIDAY VOICE", "--", "MUTE", self.toggle_voice
        )
        layout.addLayout(self.voice_row["layout"])

        layout.addSpacing(10)

        # ---- POWER (Batman logo instead of a power glyph) -------------
        self.power_button = QPushButton()
        self.power_button.setObjectName("powerButton")
        self.power_button.setIcon(load_batman_icon())
        self.power_button.setIconSize(QSize(52, 26))
        self.power_button.setFixedHeight(44)
        self.power_button.setCursor(Qt.CursorShape.PointingHandCursor)
        self.power_button.clicked.connect(self.show_power_menu)

        layout.addWidget(self.power_button)

        self.setLayout(layout)

        # Only poll status while the panel is actually open, so 26
        # isn't spawning netsh/PowerShell in the background forever.
        self.refresh_timer = QTimer(self)
        self.refresh_timer.timeout.connect(self.refresh)

        # Keeps references to in-flight _BackgroundTask threads so
        # Python doesn't garbage-collect them mid-run.
        self._workers = []

    def _run_async(self, fn, on_result):
        worker = _BackgroundTask(fn, self)

        def handle(result):
            on_result(result)
            if worker in self._workers:
                self._workers.remove(worker)

        worker.done.connect(handle)
        self._workers.append(worker)
        worker.start()

    # --------------------------------------------------------
    # ROW BUILDER
    # --------------------------------------------------------

    def _make_row(self, title_text, value_text, button_text, on_click):

        row = QHBoxLayout()

        title = QLabel(title_text)
        title.setObjectName("cardTitle")

        value = QLabel(value_text)
        value.setObjectName("detailValue")

        button = QPushButton(button_text)
        button.setFixedWidth(84)
        button.setCursor(Qt.CursorShape.PointingHandCursor)
        button.clicked.connect(on_click)

        row.addWidget(title)
        row.addStretch()
        row.addWidget(value)
        row.addWidget(button)

        return {
            "layout": row,
            "title": title,
            "value": value,
            "button": button,
        }

    def _clear_layout(self, layout):
        while layout.count():
            item = layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()

    def _list_message(self, layout, text):
        self._clear_layout(layout)
        label = QLabel(text)
        label.setObjectName("cardDetail")
        layout.addWidget(label)

    # --------------------------------------------------------
    # SHOW / HIDE
    # --------------------------------------------------------

    def show_near(self, anchor_widget):
        anchor_pos = anchor_widget.mapToGlobal(
            QPoint(0, anchor_widget.height() + 8)
        )

        # Keep the panel from running off the right edge of the screen.
        target_x = anchor_pos.x() + anchor_widget.width() - self.width()

        self.move(max(target_x, 0), anchor_pos.y())

        # Show immediately with whatever labels are already there,
        # THEN kick off status queries in the background. Doing the
        # netsh/PowerShell calls before .show() was exactly what made
        # the panel feel like it "hung" for a moment every time you
        # opened it.
        self.show()
        self.raise_()
        self.activateWindow()
        self.refresh()

    def showEvent(self, event):
        super().showEvent(event)
        self.refresh_timer.start(4000)

    def hideEvent(self, event):
        super().hideEvent(event)
        self.refresh_timer.stop()
        # Collapse the expandable lists so re-opening the panel
        # starts clean instead of showing stale scan results.
        self.wifi_list.hide()
        self.bluetooth_list.hide()

    # --------------------------------------------------------
    # LIVE STATUS
    #
    # Every call in here that shells out to netsh/PowerShell runs via
    # _run_async so it never blocks the GUI thread — that blocking is
    # what made the ring animation stutter and the panel feel like it
    # hung when tapped.
    # --------------------------------------------------------

    def refresh(self):
        self._run_async(self.hud.get_wifi_status, self._apply_wifi_status)
        self._run_async(self.hud.get_bluetooth_status, self._apply_bluetooth_status)

        self.update_voice_label()

        if self.wifi_list.isVisible():
            self.populate_wifi_networks()

        if self.bluetooth_list.isVisible():
            self.populate_bluetooth_devices()

    def _apply_wifi_status(self, result):
        if result is None:
            return
        _, label = result
        self.wifi_row["value"].setText(label)

    def _apply_bluetooth_status(self, result):
        if result is None:
            return
        _, label = result
        self.bluetooth_row["value"].setText(label)

    def update_voice_label(self):
        running = bool(
            self.hud.friday and self.hud.friday.running
        )
        self.voice_row["value"].setText(
            "LISTENING" if running else "MUTED"
        )
        self.voice_row["button"].setText(
            "MUTE" if running else "ENABLE"
        )

    # --------------------------------------------------------
    # WI-FI LIST
    # --------------------------------------------------------

    def toggle_wifi_list(self):
        if self.wifi_list.isVisible():
            self.wifi_list.hide()
            return

        self.bluetooth_list.hide()
        self.wifi_list.show()
        self.populate_wifi_networks()

    def populate_wifi_networks(self):
        self._list_message(self.wifi_list_layout, "SCANNING...")

        def collect():
            networks = self.hud.get_wifi_networks()
            connected, connected_label = self.hud.get_wifi_status()
            current_ssid = (
                connected_label.split("—", 1)[-1].strip()
                if connected else None
            )
            return networks, connected, current_ssid

        self._run_async(collect, self._apply_wifi_networks)

    def _apply_wifi_networks(self, result):
        if result is None:
            self._list_message(self.wifi_list_layout, "SCAN FAILED")
            return

        networks, connected, current_ssid = result

        self._clear_layout(self.wifi_list_layout)

        if not networks:
            self._list_message(
                self.wifi_list_layout,
                "NO NETWORKS FOUND"
            )
            return

        for net in networks[:8]:
            ssid = net["ssid"]
            secured = net["secured"]
            signal = net["signal"]
            is_current = connected and ssid == current_ssid

            row = QHBoxLayout()

            lock = "🔒" if secured else "🔓"
            name = QLabel(f"{lock} {ssid}")
            name.setObjectName("detailValue")

            signal_label = QLabel(f"{signal}%")
            signal_label.setObjectName("cardDetail")

            connect_button = QPushButton(
                "CONNECTED" if is_current else "CONNECT"
            )
            connect_button.setFixedWidth(90)
            connect_button.setEnabled(not is_current)
            connect_button.setCursor(Qt.CursorShape.PointingHandCursor)
            connect_button.clicked.connect(
                lambda _checked=False, s=ssid, sec=secured:
                    self.handle_wifi_connect(s, sec)
            )

            row.addWidget(name)
            row.addStretch()
            row.addWidget(signal_label)
            row.addWidget(connect_button)

            wrapper = QWidget()
            wrapper.setLayout(row)
            self.wifi_list_layout.addWidget(wrapper)

    def handle_wifi_connect(self, ssid, secured):
        self._list_message(
            self.wifi_list_layout,
            f"CONNECTING TO {ssid.upper()}..."
        )

        self._run_async(
            lambda: self.hud.wifi_connect_known(ssid),
            lambda result: self._on_known_connect_result(result, ssid, secured),
        )

    def _on_known_connect_result(self, result, ssid, secured):
        ok = bool(result and result[0])

        if ok:
            QTimer.singleShot(3000, self.populate_wifi_networks)
            return

        # No saved profile (or it failed) — ask for a password if this
        # network is secured. QInputDialog is modal by design, which
        # is expected UX, not a hang: it only waits on YOU, not on a
        # subprocess call.
        password = None

        if secured:
            password, accepted = QInputDialog.getText(
                self,
                f"Connect to {ssid}",
                "Wi-Fi password:",
                QLineEdit.EchoMode.Password,
            )
            if not accepted:
                self.populate_wifi_networks()
                return

        self._run_async(
            lambda: self.hud.wifi_connect_with_profile(ssid, password, secured),
            lambda result: self._on_profile_connect_result(result, ssid),
        )

    def _on_profile_connect_result(self, result, ssid):
        ok = bool(result and result[0])

        if not ok:
            message = result[1] if result else "unknown error"
            print("[26] WiFi connect failed:", message)
            self._list_message(
                self.wifi_list_layout,
                "COULDN'T CONNECT — OPENING SETTINGS"
            )
            QTimer.singleShot(900, self.open_wifi_settings)
            return

        self._list_message(
            self.wifi_list_layout,
            f"CONNECTING TO {ssid.upper()}..."
        )
        QTimer.singleShot(3000, self.populate_wifi_networks)

    # --------------------------------------------------------
    # BLUETOOTH LIST
    # --------------------------------------------------------

    def toggle_bluetooth_list(self):
        if self.bluetooth_list.isVisible():
            self.bluetooth_list.hide()
            return

        self.wifi_list.hide()
        self.bluetooth_list.show()
        self.populate_bluetooth_devices()

    def populate_bluetooth_devices(self):
        self._list_message(self.bluetooth_list_layout, "LOADING...")
        self._run_async(self.hud.get_bluetooth_devices, self._apply_bluetooth_devices)

    def _apply_bluetooth_devices(self, devices):
        if devices is None:
            devices = []

        self._clear_layout(self.bluetooth_list_layout)

        if not devices:
            self._list_message(
                self.bluetooth_list_layout,
                "NO DEVICES FOUND"
            )
        else:
            for device in devices[:8]:
                row = QHBoxLayout()

                name = QLabel(device["name"])
                name.setObjectName("detailValue")

                status = QLabel(device["status"].upper())
                status.setObjectName("cardDetail")

                row.addWidget(name)
                row.addStretch()
                row.addWidget(status)

                wrapper = QWidget()
                wrapper.setLayout(row)
                self.bluetooth_list_layout.addWidget(wrapper)

        # Pairing a new device needs Windows' own interactive pairing
        # dialog (PIN/consent) — no script can substitute for that, so
        # this always hands off to the real, correct flow.
        add_device_button = QPushButton("+ ADD DEVICE")
        add_device_button.setCursor(Qt.CursorShape.PointingHandCursor)
        add_device_button.clicked.connect(self.open_bluetooth_settings)
        self.bluetooth_list_layout.addWidget(add_device_button)

    # --------------------------------------------------------
    # ACTIONS
    # --------------------------------------------------------

    def toggle_voice(self):
        if not self.hud.friday:
            return

        if self.hud.friday.running:
            self.hud.friday.stop()
        else:
            self.hud.friday.start()

        self.update_voice_label()

    def open_wifi_settings(self):
        try:
            os.startfile("ms-settings:network-wifi")
        except Exception as error:
            print("[26] Could not open Wi-Fi settings:", repr(error))

    def open_bluetooth_settings(self):
        try:
            os.startfile("ms-settings:bluetooth")
        except Exception as error:
            print("[26] Could not open Bluetooth settings:", repr(error))

    def open_sound_settings(self):
        try:
            os.startfile("ms-settings:sound")
        except Exception as error:
            print("[26] Could not open Sound settings:", repr(error))

    def show_power_menu(self):
        menu = QMenu(self)
        menu.setObjectName("powerMenu")

        lock_action = menu.addAction("LOCK")
        sleep_action = menu.addAction("SLEEP")
        restart_action = menu.addAction("RESTART")
        shutdown_action = menu.addAction("SHUT DOWN")

        position = self.power_button.mapToGlobal(
            QPoint(0, -menu.sizeHint().height() - 4)
        )
        chosen = menu.exec(position)

        if chosen == lock_action:
            self.lock_pc()
        elif chosen == sleep_action:
            self.sleep_pc()
        elif chosen == restart_action:
            self.hud.restart_pc()
            self.hide()
        elif chosen == shutdown_action:
            self.hud.shutdown_pc()
            self.hide()

    def lock_pc(self):
        subprocess.Popen(
            "rundll32.exe user32.dll,LockWorkStation",
            shell=True
        )
        self.hide()

    def sleep_pc(self):
        subprocess.Popen(
            "rundll32.exe powrprof.dll,SetSuspendState 0,1,0",
            shell=True
        )
        self.hide()


# ============================================================
# RUNNING-APPS SWITCHER ("TASK VIEW")
# ============================================================
#
# Windows' 3/4-finger trackpad swipe (and Win+Tab) opens Task View
# and the virtual-desktop switcher. That gesture is captured by the
# Windows Shell itself before it ever reaches a regular desktop app
# — there's no supported hook for a background app like 26 to see it,
# let alone replace it. Scripting actual new *virtual desktops* the
# way Windows does has no public API either; the only ways in use
# rely on undocumented interfaces that shift between Windows builds
# and can silently break. Rather than bolt on something fragile for
# either of those, this panel (press D) gives you the part that IS
# fully reliable: a fast, Batman-styled list of every app you
# currently have open, one click to jump to any of them.
# ============================================================

class TaskViewPanel(QFrame):

    def __init__(self, hud):

        super().__init__(hud)

        self.hud = hud

        self.setObjectName("taskView")

        self.setWindowFlags(
            Qt.WindowType.FramelessWindowHint |
            Qt.WindowType.Tool
        )

        self.setFixedWidth(440)

        self.hide()

        layout = QVBoxLayout()

        layout.setContentsMargins(22, 18, 22, 18)
        layout.setSpacing(10)

        title = QLabel("26  //  RUNNING APPS")
        title.setObjectName("edition")
        layout.addWidget(title)

        self.list_container = QWidget()
        self.list_layout = QVBoxLayout(self.list_container)
        self.list_layout.setContentsMargins(0, 4, 0, 0)
        self.list_layout.setSpacing(5)

        layout.addWidget(self.list_container)

        self.setLayout(layout)

    def show_centered(self):
        self.populate()

        screen = QApplication.primaryScreen().geometry()
        x = screen.center().x() - self.width() // 2
        y = max(screen.center().y() - self.height() // 2, 40)

        self.move(x, y)
        self.show()
        self.raise_()
        self.activateWindow()

    def populate(self):
        while self.list_layout.count():
            item = self.list_layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()

        windows = self.hud.list_open_windows()

        if not windows:
            label = QLabel("NOTHING ELSE OPEN RIGHT NOW")
            label.setObjectName("cardDetail")
            self.list_layout.addWidget(label)
            return

        for win in windows[:10]:
            row = QHBoxLayout()

            name = QLabel(win["title"][:52])
            name.setObjectName("detailValue")

            process = QLabel(win["process"].upper())
            process.setObjectName("cardDetail")

            switch_button = QPushButton("SWITCH")
            switch_button.setFixedWidth(84)
            switch_button.setCursor(Qt.CursorShape.PointingHandCursor)
            switch_button.clicked.connect(
                lambda _checked=False, h=win["hwnd"], p=win["process"]:
                    self.switch_to(h, p)
            )

            row.addWidget(name, 2)
            row.addWidget(process, 1)
            row.addWidget(switch_button)

            wrapper = QWidget()
            wrapper.setLayout(row)
            self.list_layout.addWidget(wrapper)

    def switch_to(self, hwnd, process_name):
        self.hud.switch_to_window(hwnd, process_name)
        self.hide()


# ============================================================
# MAIN HUD
# ============================================================

class HUD26(QWidget):

    def position_search_results(self):

        if not self.search.isVisible():
            return

        pos = self.search.mapToGlobal(
            QPoint(
                0,
                self.search.height() + 5
            )
        )

        self.results.move(
            self.mapFromGlobal(pos)
        )

    def friday_state(self, state):

    # Update whatever status label your HUD uses.
    # If your current HUD has self.network, this works immediately.

        if hasattr(self, "network"):

            self.network.setText(
                f"FRIDAY   //   {state}"
            )


    def friday_command(self, command):

        # Friday calls this callback immediately BEFORE executing the
        # command.  For external applications we must get the Batman HUD
        # out of the way first, otherwise its always-on-top flag can cover
        # the application.
        print(f"Boss command: {command}")

        lower = command.strip().lower()
        if lower.startswith(("open ", "launch ", "start ")):
            app_name = lower.split(" ", 1)[1].strip()

            # Keep 26 hidden while the launched application owns the
            # screen, then watch for it and come back automatically.
            self.prepare_for_external_app(app_name)


    def __init__(self):

        super().__init__()

        # External-app session state.
        # These attributes belong to HUD26 because monitor_external_app()
        # and restore_hud() run on the HUD object.
        #
        # _awaiting_external_app is the "are we currently hidden and
        # watching for something to come back from" flag. It is set
        # any time we hide 26 to launch something, regardless of
        # whether we know that app's name.
        #
        # _pending_external_app is only a NAME FILTER used to narrow
        # which foreground window counts as "the app arrived" when we
        # do know the name. It can legitimately be None/empty.
        self._awaiting_external_app = False
        self._pending_external_app = None
        self._external_app_hwnd = 0
        self._external_app_pid = None
        self._external_watch_deadline = 0.0
        self._pending_confirm_hwnd = 0
        self._our_pid = os.getpid()
        self._desktop_docked = False

        self.batman_font = get_batman_font()

        self.setWindowTitle(
            "26 // BATMAN EDITION"
        )

        if ENABLE_DESKTOP_DOCK:
            # Start WITHOUT the always-on-top flag: if desktop docking
            # succeeds below, topmost would fight the whole point of
            # sitting behind normal app windows. try_dock_to_desktop()
            # adds the topmost flag back on failure -- and it does so
            # BEFORE showFullScreen() is ever called, so this window
            # only gets shown once, with its flags already final.
            #
            # (The previous version showed fullscreen immediately,
            # then tried docking ~400ms later and re-applied flags +
            # showFullScreen() a SECOND time on failure. Changing
            # window flags after a window has already been shown
            # fullscreen makes Qt recreate the native window, and Qt
            # doesn't reliably reapply fullscreen geometry to that new
            # native window -- which is exactly what produced the
            # "half window" bug.)
            self.setWindowFlags(
                Qt.WindowType.FramelessWindowHint
            )
        else:
            self.setWindowFlags(
                Qt.WindowType.FramelessWindowHint |
                Qt.WindowType.WindowStaysOnTopHint
            )

        self.setup_style()

        self.setup_ui()

        self.load_applications()

        self.timer = QTimer(self)

        self.timer.timeout.connect(
            self.update_system
        )

        self.timer.start(1000)

        # Watches an application launched by Friday.  When that application
        # closes, 26 automatically returns to the Batman screen.
        self.app_watch_timer = QTimer(self)
        self.app_watch_timer.timeout.connect(
            self.monitor_external_app
        )
        self.app_watch_timer.start(400)

        self.friday = FridayVoice(
            on_state_change=self.friday_state,
            on_command=self.friday_command
        )

        self.friday.start()

        self.quick_settings = QuickSettingsPanel(self)

        self.task_view = TaskViewPanel(self)

        self.update_system()

        if ENABLE_DESKTOP_DOCK:
            # Runs synchronously, before the one-and-only showFullScreen()
            # call below, so window flags are fully decided first.
            self.try_dock_to_desktop()

        self.showFullScreen()

