    # ========================================================
    # APPLICATION DISCOVERY
    # ========================================================

    def load_applications(self):

        # Windows Start Menu contains both normal .lnk apps and
        # modern Store/MSIX apps such as WhatsApp and Spotify.
        # Build one unified application table for the HUD.
        self.applications = {}

        locations = [

            Path(
                os.environ.get(
                    "APPDATA",
                    ""
                )
            )
            / "Microsoft/Windows/Start Menu/Programs",

            Path(
                os.environ.get(
                    "PROGRAMDATA",
                    ""
                )
            )
            / "Microsoft/Windows/Start Menu/Programs",
        ]

        for location in locations:

            if not location.exists():
                continue

            try:

                for file in location.rglob("*.lnk"):

                    name = file.stem.strip()

                    if name:
                        self.applications[name] = {
                            "type": "path",
                            "target": str(file),
                        }

            except Exception as error:

                print(
                    "Start Menu scan error:",
                    error
                )

        # Add Microsoft Store / MSIX / registered Windows apps.
        # Get-StartApps returns the real AppID Windows expects.
        try:

            result = subprocess.run(
                [
                    "powershell.exe",
                    "-NoProfile",
                    "-ExecutionPolicy",
                    "Bypass",
                    "-Command",
                    'Get-StartApps | ForEach-Object { "$($_.Name)||$($_.AppID)" }'
                ],
                capture_output=True,
                text=True,
                timeout=12
            )

            for line in result.stdout.splitlines():

                if "||" not in line:
                    continue

                name, app_id = line.split("||", 1)
                name = name.strip()
                app_id = app_id.strip()

                if name and app_id:
                    self.applications[name] = {
                        "type": "app_id",
                        "target": app_id,
                    }

        except Exception as error:

            print(
                "Windows app discovery error:",
                error
            )

        print(
            f"[26] Applications loaded: {len(self.applications)}"
        )

    # ========================================================
    # SEARCH
    # ========================================================

    def search_apps(
        self,
        text
    ):

        text = text.strip().lower()

        if not text:

            self.results.hide()

            return

        matches = []

        for name in self.applications:

            if text in name.lower():

                matches.append(
                    name
                )

        matches.sort(
            key=lambda x: (
                not x.lower().startswith(
                    text
                ),
                x.lower()
            )
        )

        matches = matches[:8]

        self.results_model.setStringList(
            matches
        )

        if matches:

            self.position_search_results()
            self.results.show()

        else:

            self.results.hide()

    # ========================================================
    # BATMAN SHELL / EXTERNAL APPLICATION MANAGEMENT
    # ========================================================

    def try_dock_to_desktop(self):
        """Attach 26 to the WorkerW layer Windows uses for rich
        wallpapers, so normal app windows stack on top of it via
        ordinary Windows z-ordering instead of us hiding/restoring
        it in code. See the ENABLE_DESKTOP_DOCK comment near the top
        of this file for the full explanation and the trade-offs.

        Falls back to the previous always-on-top + hide/restore
        behavior automatically if anything here doesn't work out.
        """
        try:
            user32 = ctypes.windll.user32

            user32.FindWindowW.restype = wintypes.HWND
            user32.FindWindowW.argtypes = [
                wintypes.LPCWSTR, wintypes.LPCWSTR
            ]
            user32.FindWindowExW.restype = wintypes.HWND
            user32.FindWindowExW.argtypes = [
                wintypes.HWND, wintypes.HWND,
                wintypes.LPCWSTR, wintypes.LPCWSTR,
            ]
            user32.SetParent.restype = wintypes.HWND
            user32.SetParent.argtypes = [wintypes.HWND, wintypes.HWND]
            user32.SendMessageTimeoutW.restype = ctypes.c_void_p
            user32.SendMessageTimeoutW.argtypes = [
                wintypes.HWND, wintypes.UINT,
                wintypes.WPARAM, wintypes.LPARAM,
                wintypes.UINT, wintypes.UINT,
                ctypes.POINTER(wintypes.DWORD),
            ]

            progman = user32.FindWindowW("Progman", None)
            if not progman:
                raise RuntimeError("Progman window not found")

            # Undocumented message that asks Progman to spawn the
            # WorkerW used for hosting rich wallpaper content. This
            # exact call is what wallpaper tools have relied on since
            # Windows 7.
            result = wintypes.DWORD()
            user32.SendMessageTimeoutW(
                progman, 0x052C, 0, 0, 0x0000, 1000, ctypes.byref(result)
            )

            # There's a known race here: the WorkerW doesn't always
            # exist the instant after the message above returns. Give
            # it a few short retries before giving up.
            workerw = None

            for _attempt in range(5):
                time.sleep(0.15)

                found_workerw = []

                @ctypes.WINFUNCTYPE(ctypes.c_bool, wintypes.HWND, wintypes.LPARAM)
                def enum_proc(hwnd, _lparam):
                    defview = user32.FindWindowExW(
                        hwnd, None, "SHELLDLL_DefView", None
                    )
                    if defview:
                        found_workerw.append(
                            user32.FindWindowExW(None, hwnd, "WorkerW", None)
                        )
                    return True

                user32.EnumWindows(enum_proc, 0)

                workerw = found_workerw[0] if found_workerw else None
                if workerw:
                    break

            if not workerw:
                raise RuntimeError("WorkerW not found")

            our_hwnd = int(self.winId())
            user32.SetParent(our_hwnd, workerw)

            screen = QApplication.primaryScreen().geometry()
            self.setGeometry(0, 0, screen.width(), screen.height())

            self._desktop_docked = True
            print(
                "[26] Docked to the desktop layer — "
                "26 now stays visible under every app, no hide/restore needed."
            )

        except Exception as error:
            print(
                "[26] Desktop docking unavailable on this machine "
                f"({repr(error)}); staying in always-on-top mode instead."
            )
            self._desktop_docked = False
            self.setWindowFlags(
                Qt.WindowType.FramelessWindowHint |
                Qt.WindowType.WindowStaysOnTopHint
            )
            # Note: no showFullScreen() here on purpose. This method now
            # always runs BEFORE __init__'s one-and-only showFullScreen()
            # call, so flags are fully decided first and the window is
            # shown fullscreen exactly once, correctly sized either way.

    def prepare_for_external_app(self, app_name=None):
        """Hide 26 and start watching for the launched app's window.

        This is now the ONE place every launch path routes through —
        Friday voice commands, the search bar, and the quick-access
        buttons. Previously only the voice-command path set
        _pending_external_app, so it was the only path the watchdog
        below would ever wake up for; the search bar and quick-access
        buttons just called hide() with nothing to bring 26 back,
        which is why 26 was disappearing for good every time you
        opened something that way.

        app_name narrows matching to a specific app when we know it.
        When it's None, ANY new foreground window (other than 26
        itself and core Windows shell surfaces) counts as "the app
        arrived" — and there is always an 8-second failsafe in
        monitor_external_app() that restores 26 even if nothing ever
        matches, so 26 can no longer get stuck hidden indefinitely.

        When desktop-docked (see try_dock_to_desktop), none of this
        is needed at all — 26 lives behind every app window via
        normal Windows stacking, so we just let the launch happen.

        Note this deliberately does NOT hide 26 yet. 26 is always-on-
        top, so it keeps covering the real desktop while the new app
        starts up behind it — Windows still tracks that app as the
        "foreground" window (GetForegroundWindow) even while it's
        rendering underneath us, occluded but fully drawn. We only
        hide once capture_external_app_window() below confirms it, so
        the instant 26 disappears the app is already sitting there
        ready — instead of the previous behavior of hiding first and
        THEN waiting, which exposed the real Windows desktop/wallpaper
        for however long the app took to start.
        """
        if self._desktop_docked:
            return

        self._pending_external_app = app_name
        self._awaiting_external_app = True
        self._external_app_hwnd = 0
        self._external_app_pid = None
        self._pending_confirm_hwnd = 0
        self._external_watch_deadline = time.monotonic() + 8.0

        QTimer.singleShot(150, self.capture_external_app_window)

    def _foreground_window_info(self):
        try:
            user32 = ctypes.windll.user32
            hwnd = user32.GetForegroundWindow()
            if not hwnd:
                return 0, None, ""

            pid = wintypes.DWORD()
            user32.GetWindowThreadProcessId(
                wintypes.HWND(hwnd),
                ctypes.byref(pid)
            )

            title_buf = ctypes.create_unicode_buffer(512)
            user32.GetWindowTextW(
                wintypes.HWND(hwnd),
                title_buf,
                512
            )

            return int(hwnd), int(pid.value), title_buf.value.strip()
        except Exception:
            return 0, None, ""

    def _process_name(self, pid):
        if not pid:
            return ""
        try:
            return psutil.Process(pid).name().lower()
        except Exception:
            return ""

    def _looks_like_target_app(self, pid, title):
        if not pid or pid == self._our_pid:
            return False

        process_name = self._process_name(pid)
        requested = (self._pending_external_app or "").lower()

        # "Open Files" deliberately launches Explorer itself, so let it
        # through even though Explorer is ignored in every other case
        # below (it also hosts the desktop/taskbar, which we don't want
        # to mistake for a launched app the rest of the time).
        if process_name == "explorer.exe" and requested == "files":
            return True

        # Ignore Windows shell/system surfaces while waiting for the app.
        ignored = {
            "explorer.exe",
            "dwm.exe",
            "sihost.exe",
            "searchhost.exe",
            "startmenuexperiencehost.exe",
            "textinputhost.exe",
            "lockapp.exe",
        }
        if process_name in ignored:
            return False

        if not requested:
            return True

        words = [
            w for w in requested.replace("-", " ").split()
            if len(w) > 2
        ]

        haystack = f"{process_name} {title.lower()}"
        if any(w in haystack for w in words):
            return True

        # Chrome/Edge often use a webpage title, so identify by process.
        if requested in ("chrome", "google chrome") and process_name == "chrome.exe":
            return True
        if requested in ("edge", "microsoft edge") and process_name == "msedge.exe":
            return True

        # Store apps can use ApplicationFrameHost as their visible host.
        # Accept it after the target has had time to activate.
        if process_name == "applicationframehost.exe" and title:
            return True

        return False

    def capture_external_app_window(self):
        if not self._awaiting_external_app:
            return

        hwnd, pid, title = self._foreground_window_info()

        if self._looks_like_target_app(pid, title):
            # Require the SAME window to still be foreground a beat
            # later before committing to hide. Some apps (Chrome,
            # WhatsApp, and plenty of others) grab foreground focus
            # for a placeholder/splash window an instant before their
            # real content is actually painted -- hiding 26 the moment
            # THAT counts as a match exposes the bare desktop
            # underneath for that gap, which is exactly what you were
            # seeing (now showing the Batman wallpaper instead of a
            # random one, which is why it became more noticeable, not
            # less). Confirming twice, ~150ms apart, gives the app a
            # moment to settle before 26 reveals it.
            if self._pending_confirm_hwnd == hwnd:
                self._external_app_hwnd = hwnd
                self._external_app_pid = pid
                self._pending_confirm_hwnd = 0

                self.hide()

                print(
                    f"[26] External app active: "
                    f"PID={pid} PROCESS={self._process_name(pid)} TITLE={title!r}"
                )
                return

            self._pending_confirm_hwnd = hwnd
        else:
            self._pending_confirm_hwnd = 0

        # Keep checking for up to 8 seconds while the application starts.
        if time.monotonic() < self._external_watch_deadline:
            QTimer.singleShot(150, self.capture_external_app_window)

    def monitor_external_app(self):
        if not self._awaiting_external_app:
            return

        # We are waiting for the target app to become foreground.
        if not self._external_app_hwnd:
            if time.monotonic() > self._external_watch_deadline:
                # Do not leave the user with a black/hidden desktop forever.
                print("[26] External app activation timeout; restoring HUD.")
                self.restore_hud()
            return

        user32 = ctypes.windll.user32

        hwnd_handle = wintypes.HWND(self._external_app_hwnd)

        # A destroyed window invalidates the handle -- but plenty of
        # apps (WhatsApp, Discord, Telegram, Slack, and most other
        # tray-resident apps) don't actually destroy their window when
        # you close it: they just hide it and keep running in the
        # background. IsWindow() alone stays True forever for that
        # case, which is exactly why 26 wasn't coming back after using
        # an app like WhatsApp. IsWindowVisible() catches that case
        # too, while still leaving a normal taskbar-minimize alone
        # (a minimized-but-not-hidden window still reports visible).
        window_destroyed = not user32.IsWindow(hwnd_handle)
        window_hidden = (
            not window_destroyed and
            not user32.IsWindowVisible(hwnd_handle)
        )

        if window_destroyed or window_hidden:
            print("[26] External app window closed or hidden; restoring HUD.")
            self.restore_hud()
            return

        # If we captured a host process that has exited, restore too.
        if self._external_app_pid and not psutil.pid_exists(self._external_app_pid):
            print("[26] External app process ended; restoring HUD.")
            self.restore_hud()

    def restore_hud(self):
        self._pending_external_app = None
        self._awaiting_external_app = False
        self._external_app_hwnd = 0
        self._external_app_pid = None
        self._external_watch_deadline = 0.0

        self.showFullScreen()
        self.raise_()
        self.activateWindow()
        QApplication.processEvents()

    def ensure_startup(self):
        """Create (or repair) a per-user Windows Startup shortcut so 26
        is the first thing that opens after every login.

        This used to fail silently: if the PowerShell call errored out,
        the only sign was a print() that nobody sees when the app is
        launched by double-click. It now writes a small log file next
        to the script AND verifies the .lnk actually exists afterward,
        so "it didn't come back after I restarted" is diagnosable
        instead of a mystery.
        """
        log_path = Path(__file__).resolve().parent / "_26_startup_log.txt"

        def log(message):
            try:
                with open(log_path, "a", encoding="utf-8") as handle:
                    handle.write(
                        f"{datetime.now().isoformat(timespec='seconds')}  {message}\n"
                    )
            except Exception:
                pass
            print(f"[26] {message}")

        try:
            startup_dir = Path(
                os.environ.get(
                    "APPDATA",
                    ""
                )
            ) / "Microsoft/Windows/Start Menu/Programs/Startup"

            startup_dir.mkdir(parents=True, exist_ok=True)
            shortcut = startup_dir / "26 Batman Edition.lnk"

            # Prefer pythonw.exe (same folder as the interpreter that's
            # running us) so login launches straight into the fullscreen
            # HUD without a black console window flashing up first. Fall
            # back to the normal interpreter if pythonw isn't there.
            python_exe = sys.executable
            pythonw_candidate = Path(python_exe).with_name("pythonw.exe")
            if pythonw_candidate.exists():
                python_exe = str(pythonw_candidate)

            script = str(Path(__file__).resolve())
            working_dir = str(Path(__file__).resolve().parent)

            # Use PowerShell to create the shortcut without requiring admin.
            ps = (
                "$ws=New-Object -ComObject WScript.Shell;"
                f"$s=$ws.CreateShortcut('{str(shortcut)}');"
                f"$s.TargetPath='{python_exe}';"
                f"$s.Arguments='-u \"{script}\"';"
                f"$s.WorkingDirectory='{working_dir}';"
                "$s.WindowStyle=7;"
                "$s.Save()"
            )

            result = subprocess.run(
                [
                    "powershell.exe",
                    "-NoProfile",
                    "-ExecutionPolicy",
                    "Bypass",
                    "-Command",
                    ps,
                ],
                capture_output=True,
                text=True,
                timeout=10,
            )

            if shortcut.exists():
                log(f"Startup shortcut ready: {shortcut} -> {python_exe}")
            else:
                log(
                    "Startup shortcut MISSING after PowerShell ran. "
                    f"returncode={result.returncode} "
                    f"stderr={result.stderr.strip()!r}"
                )

        except Exception as error:
            log(f"Startup setup FAILED: {repr(error)}")

    # ========================================================
    # HIDE HUD BEFORE LAUNCHING
    # ========================================================

    def prepare_for_launch(self, app_name=None):

        # Used by the search bar and the quick-access buttons.
        #
        # This now shares the exact same watch-and-restore logic as
        # Friday's voice-launched apps (see prepare_for_external_app),
        # instead of just hiding with no way back. That gap was the
        # actual bug: 26 would vanish the moment you launched anything
        # this way and never reappear, even after the app closed or
        # you shut down and logged back in.

        self.prepare_for_external_app(app_name)

    # ========================================================
    # SEARCH LAUNCH
    # ========================================================

    def launch_first_result(self):

        results = (
            self.results_model
            .stringList()
        )

        if not results:

            return

        self.launch_application(
            results[0]
        )

    def launch_selected_result(
        self,
        index
    ):

        name = (
            self.results_model
            .data(index)
        )

        if name:

            self.launch_application(
                name
            )

    def launch_application(
        self,
        name
    ):

        app = self.applications.get(name)

        if not app:
            print(
                f"[26] Application not found: {name}"
            )
            return False

        try:

            self.prepare_for_launch(name)

            if app["type"] == "app_id":

                # Modern Store/MSIX application.
                subprocess.Popen(
                    [
                        "explorer.exe",
                        f"shell:AppsFolder\\{app['target']}"
                    ]
                )

            else:

                # Traditional Start Menu shortcut.
                os.startfile(
                    app["target"]
                )

            print(
                f"[26] Launched: {name}"
            )

            self.search.clear()
            self.results.hide()
            return True

        except Exception as error:

            print(
                "Application launch error:",
                error
            )

            self.show()
            return False

